use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientIdTokenEncryptedResponseAlgAccessor trait.
 *
 * Covers null default, string/VO assignment via withIdTokenEncryptedResponseAlg,
 * getIdTokenEncryptedResponseAlg/idTokenEncryptedResponseAlg accessors, and isIdTokenEncryptedResponseAlgChanged with/without original.
 */
class TrustedClientIdTokenEncryptedResponseAlgAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withIdTokenEncryptedResponseAlg creates a new instance with the IdTokenEncryptedResponseAlg set
     * from a string value, and getIdTokenEncryptedResponseAlg returns the primitive string.
     */
    public function testWithIdTokenEncryptedResponseAlgFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenEncryptedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withIdTokenEncryptedResponseAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getIdTokenEncryptedResponseAlg());
    }
    /**
     * Asserts that withidTokenEncryptedResponseAlg has access to the value object
     * from a string value, and getIdTokenEncryptedResponseAlg returns the primitive string.
     */
    public function testWithIdTokenEncryptedResponseAlgFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenEncryptedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withIdTokenEncryptedResponseAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->idTokenEncryptedResponseAlg()->value());
    }
    public function testChangedIdTokenEncryptedResponseAlg(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIdTokenEncryptedResponseAlgAccessorUnitTest();
        $original = $holder->withIdTokenEncryptedResponseAlg('one');
        $same = $holder->withIdTokenEncryptedResponseAlg('one');
        $modified = $holder->withIdTokenEncryptedResponseAlg('other');

        // Act
        $unchanged = $holder->isIdTokenEncryptedResponseAlgChanged();
        $withSame = $original->isIdTokenEncryptedResponseAlgChanged($same);
        $withDiferent = $original->isIdTokenEncryptedResponseAlgChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
